  ;
  -- **A missing heading means two different things, split by how the
  -- placement arrived.** A *candidate* heading travelled with the items file,
  -- so its absence means the pass was asked about an ontology that has since
  -- moved — a broken run, and it raises. An *inherited* heading came from
  -- catalogue ancestry, which includes runtime-minted concepts (`kept_` keys,
  -- the genre miner's `genre:britpop`) that a clean replay legitimately does
  -- not hold — those resolve best-effort and the misses are counted, because
  -- the first version raised on `genre:britpop` and made the whole load
  -- unreplayable over a heading production genuinely holds.
  select string_agg(distinct p.parent_key, ', ') into missing
    from _placement p
   where p.strict
     and not exists (select 1 from ontology.concepts c
                      where c.concept_key = p.parent_key
                        and c.retired_at is null);
  if missing is not null then
    raise exception '%: placement names candidate headings this database does not hold: %',
      '0344', missing;
  end if;
  select string_agg(distinct p.parent_key, ', ') into missing
    from _placement p
   where not p.strict
     and not exists (select 1 from ontology.concepts c
                      where c.concept_key = p.parent_key
                        and c.retired_at is null);
  if missing is not null then
    raise notice '%: inherited headings not held here, skipped: %',
      '0344', missing;
  end if;

  update semantic_private.presumed_terms t
     set proposed_parent_concept_id = c.id,
         proposed_parent_confidence_unvalidated = p.confidence,
         proposed_parent_source = 'placement_pass'
    from _placement p
    join ontology.concepts c
      on c.concept_key = p.parent_key and c.retired_at is null
   where t.normalized_label = p.normalized_label
     and t.family = p.family;
  get diagnostics n = row_count;
  raise notice '%: % of % placements landed', '0344',
    n, (select count(*) from _placement);
  -- Zero here can only mean the join is wrong: every pair emitted was minted
  -- by the insert above, in this same migration.
  if n = 0 then
    raise exception
      '%: placements were emitted and none matched a term', '0344';
  end if;
end;
$$;

do $$
declare
  n integer;
begin
  select count(*) into n from semantic_private.presumed_terms;
  raise notice '0344: % terms in the dictionary', n;
  select count(*) into n from semantic_private.presumed_terms
   where english_label is not null;
  raise notice '0344: % carry an English label', n;
  select count(*) into n from semantic_private.presumed_terms
   where canonical_term_id is not null;
  raise notice '0344: % defer to a canonical', n;
  select count(*) into n from semantic_private.presumed_term_relations;
  raise notice '0344: % relations recorded', n;
  select count(*) into n from semantic_private.presumed_terms
   where proposed_parent_concept_id is not null;
  raise notice '0344: % carry a proposed parent', n;
  -- **The thin rows, said out loud.** 65% of this dictionary rested on a
  -- single mention when nothing promoted; the owner's 2026-08-24 direction
  -- makes discovery mint, so the number is now the one to watch.
  select count(*) into n from semantic_private.presumed_terms
   where entry_support = 1;
  raise notice '0344: % rest on a single library entry', n;
  select count(*) into n from semantic_private.presumed_terms
   where family_support_share is not null and family_support_share < 0.2;
  raise notice '0344: % are a minority reading of their own label', n;
end;
$$;

-- **Every load ends with the resolver — 0340's own rule, honoured by the
-- emitter rather than remembered by an operator.** The first load shipped
-- with 1,475 rows naming concepts the catalogue already published and none
-- linked, because resolution was a step somebody had to think of. Exact
-- identity, kind agreement, ambiguity refused; the counts land in the log.
do $$
declare
  r record;
begin
  select * into r from semantic_private.resolve_presumed_terms_to_catalogue();
  raise notice
    '0344: resolver linked %, refused % ambiguous, % kind-mismatched',
    r.linked, r.ambiguous, r.kind_mismatch;
end;
$$;

